const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('#nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!open));nav.classList.toggle('open',!open)});nav.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>{menu.setAttribute('aria-expanded','false');nav.classList.remove('open')}));
const revealObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('shown');revealObserver.unobserve(entry.target)}}),{threshold:.1});document.querySelectorAll('.reveal').forEach(el=>revealObserver.observe(el));
const form=document.querySelector('.contact-form'),submitButton=form.querySelector('button[type="submit"]'),submitLabel=submitButton.innerHTML,honeypot=form.querySelector('[name="_gotcha"]'),error=form.querySelector('.form-error');Object.assign(honeypot.style,{position:'absolute',width:'1px',height:'1px',padding:'0',margin:'-1px',overflow:'hidden',clip:'rect(0,0,0,0)',whiteSpace:'nowrap',border:'0'});Object.assign(error.style,{background:'#f7dfd8',color:'#7b3024',padding:'13px',marginTop:'16px'});error.querySelector('p').style.margin='0';form.addEventListener('submit',async event=>{event.preventDefault();let valid=true;const name=form.querySelector('#name'),email=form.querySelector('#email'),success=form.querySelector('.form-success');success.classList.remove('show');error.hidden=true;[[name,name.value.trim().length>1],[email,/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value)]].forEach(([input,ok])=>{input.closest('label').classList.toggle('invalid',!ok);input.setAttribute('aria-invalid',String(!ok));if(!ok)valid=false});if(!valid)return;submitButton.disabled=true;submitButton.textContent='Sending…';try{const response=await fetch(form.action,{method:'POST',body:new FormData(form),headers:{Accept:'application/json'}});if(!response.ok)throw new Error('Form submission failed');success.classList.add('show');success.focus();form.reset()}catch(e){error.hidden=false;error.focus()}finally{submitButton.disabled=false;submitButton.innerHTML=submitLabel}});form.querySelectorAll('input').forEach(input=>input.addEventListener('input',()=>input.closest('label')?.classList.remove('invalid')));document.querySelector('#year').textContent=new Date().getFullYear();
